<script setup>
import { computed, nextTick, ref, watch } from 'vue'
import FigmaPdfVorschau from './FigmaPdfVorschau.vue'

const props = defineProps({ step: { type: Number, default: 1 } })
const heading = ref(null)
const link = step => ({ name: 'medientechnik-figma-tutorial-4', params: { step } })
const steps = [
  { title: 'Vorlage untersuchen', intro: 'Du baust die Kategorieseite der Einkaufs-App in Figma nach.', instructions: ['Sieh dir die PDF-Vorlage an. Zähle die Kategorien und untersuche, wie sie in Zeilen und Spalten angeordnet sind.', 'Vergleiche die Abstände zwischen den Kategorien und zum Rand. Achte auf das weiße Rechteck, den Kreis, das Piktogramm und die Beschriftung jeder Kategorie.', 'Verwende die Assets aus Tutorial 3. Falls du sie noch nicht hast, lade die ZIP-Datei unten herunter und entpacke sie.'], check: 'Du erkennst das dreispaltige Raster und die Bestandteile einer Kategorie.' },
  { title: 'Kategorieseite anlegen', intro: 'Ergänze die bestehende Einkaufs-App um einen weiteren Bildschirm.', instructions: ['Öffne deine Figma-Datei „Einkaufs-App“ aus Tutorial 3.', 'Erstelle neben dem Frame „Home – Nachbau“ einen neuen Frame mit 414 × 896 und benenne ihn „Category – Nachbau“.', 'Ergänze die Statuszeile und die Überschrift „Categories“ entsprechend der Vorlage. Du kannst passende Elemente aus deiner Startseite kopieren.'], check: 'Der neue Frame enthält Statuszeile und Überschrift.' },
  { title: 'Ebenen und Reihenfolge verstehen', intro: 'Jedes Objekt erscheint als Ebene in der linken Ebenenliste. Ihre Reihenfolge bestimmt, was vor oder hinter anderen Objekten liegt.', instructions: ['Zeichne ein weißes Rechteck als Hintergrund für die Kategorie „Vegetables“. Orientiere dich an seiner Größe in der Vorlage.', 'Zeichne darauf einen hellen Kreis und füge ein passendes Piktogramm aus dem Ordner „pictograms“ darüber ein.', 'Füge die Beschriftung „Vegetables“ unter dem Kreis auf dem Rechteck als eigene Textebene hinzu.', 'Klappe „Category – Nachbau“ in der Ebenenliste auf und wähle Rechteck, Kreis, Piktogramm und Text nacheinander aus. Beobachte, welches Objekt jeweils auf der Arbeitsfläche markiert wird.', 'Benenne die Ebenen verständlich, zum Beispiel „Hintergrund“, „Kreis“, „Piktogramm“ und „Beschriftung“. Doppelklicke dazu auf den jeweiligen Namen in der Ebenenliste.', 'Ordne die Ebenen so an, dass das Rechteck hinter allen anderen Elementen und das Piktogramm vor dem Kreis liegt.'], check: 'Rechteck, Kreis, Piktogramm und Text sind als benannte Ebenen erkennbar und in der richtigen Reihenfolge sichtbar.' },
  { title: 'Kategorie ausrichten und gruppieren', intro: 'Richte die Teile einer Kategorie zueinander aus und fasse sie anschließend zusammen.', instructions: ['Wähle Kreis und Piktogramm gemeinsam aus und richte das Piktogramm mittig auf dem Kreis aus. Nutze dafür die Ausrichtungswerkzeuge im rechten Eigenschaftenbereich.', 'Richte Kreis und Beschriftung mittig auf dem weißen Rechteck aus. Prüfe die Abstände zur Vorlage.', 'Wähle Rechteck, Kreis, Piktogramm und Beschriftung gemeinsam aus und gruppiere sie mit „Auswahl gruppieren“ (Mac: ⌘G, Windows: Strg+G).', 'Benenne die Gruppe „Vegetables“. Klappe sie in der Ebenenliste auf und prüfe, ob du ihre einzelnen Elemente weiterhin auswählen und bearbeiten kannst.'], check: 'Die Gruppe „Vegetables“ enthält das weiße Rechteck und die drei ausgerichteten Elemente und lässt sich zusammen verschieben.' },
  { title: 'Erste Reihe erstellen', intro: 'Nutze die erste Gruppe als Grundlage für weitere Kategorien.', instructions: ['Dupliziere die Gruppe zweimal und ordne die Kopien rechts daneben an.', 'Benenne die Gruppen „Fruits“ und „Beverages“. Ändere jeweils Beschriftung, Kreisfarbe und Piktogramm anhand der Vorlage.', 'Wähle die drei Gruppen gemeinsam aus und richte sie an derselben Höhe aus. Verwende die Ausrichtungswerkzeuge und prüfe, ob die Abstände zwischen ihnen gleich sind.', 'Vergleiche die Außenabstände links und rechts mit der PDF.'], check: 'Drei benannte Kategorien stehen gleichmäßig in einer Reihe.' },
  { title: 'Raster vervollständigen', intro: 'Ergänze die weiteren Kategorien und achte auf die Abstände zwischen den Reihen.', instructions: ['Dupliziere die Kategorien und ergänze „Grocery“, „Edible oil“ und „Household“ in der zweiten Reihe sowie „Babycare“ darunter links.', 'Passe die Kreisfarben und Piktogramme an. Verwende die passenden Dateien aus „pictograms“; falls ein Motiv fehlt, nutze vorläufig einen einfachen Platzhalter.', 'Richte die Kategorien jeder Spalte untereinander aus. Wähle die Gruppen der jeweiligen Reihe aus und verteile sie gleichmäßig.', 'Vergleiche die Abstände zwischen den Reihen und den Abstand zur Überschrift mit der Vorlage.'], check: 'Alle sieben Kategorien stehen im Raster der Vorlage; die Gruppen sind ausgerichtet und gleichmäßig verteilt.' },
  { title: 'Ebenen übersichtlich ordnen', intro: 'Eine klare Ebenenliste macht spätere Änderungen leichter.', instructions: ['Prüfe, ob jede Kategoriegruppe einen passenden Namen trägt und ihr weißes Rechteck sowie die übrigen Elemente enthält.', 'Fasse die sieben Kategoriegruppen zu einer Gruppe „Kategorien“ zusammen. Achte darauf, dass sie innerhalb des Frames „Category – Nachbau“ liegt.', 'Klappe die Gruppen in der Ebenenliste auf und zu. Wähle eine Beschriftung innerhalb einer Gruppe aus und bearbeite sie, ohne die übrigen Kategorien zu verändern.', 'Prüfe die Reihenfolge der Ebenen: Die weißen Rechtecke liegen hinten, die Piktogramme sichtbar vor ihren Kreisen.'], check: 'Die Ebenenliste ist benannt und gegliedert; einzelne Elemente bleiben bearbeitbar.' },
  { title: 'Ergebnis überprüfen', intro: 'Vergleiche deinen Entwurf mit der PDF-Vorlage.', instructions: ['Prüfe die Reihenfolge und Schreibweise aller sieben Kategorien sowie die Anordnung in drei Spalten.', 'Kontrolliere Ausrichtung, gleichmäßige Abstände, Farben und die Position der Piktogramme.', 'Verschiebe die Gruppe „Kategorien“ probeweise und mache die Änderung anschließend rückgängig. Prüfe, ob alle Kategorien gemeinsam bewegt wurden.', 'Speichere deine Arbeit in deiner Figma-Datei.'], check: 'Deine Kategorieseite entspricht dem Aufbau der Vorlage und besitzt eine übersichtliche Ebenenstruktur.' }
]
const current = computed(() => steps[props.step - 1])
watch(() => props.step, async () => { await nextTick(); heading.value?.focus() })
</script>

<template>
  <main class="lesson-page"><div class="shell">
    <RouterLink to="/medientechnik/figma" class="back">← Figma</RouterLink>
    <header><p class="eyebrow">FIGMA · TEILTUTORIAL 4 · SCHRITT {{ step }} VON {{ steps.length }}</p><h1 ref="heading" tabindex="-1">Kategorieseite nach Vorlage in Figma gestalten</h1><p class="goal">Baue die Kategorieseite nach und übe Ebenen, Gruppen, Ausrichtung und Abstände.</p></header>
    <nav class="step-links" aria-label="Schritte dieses Tutorials"><RouterLink v-for="(item, index) in steps" :key="item.title" :to="link(index + 1)" :aria-current="step === index + 1 ? 'step' : undefined" :aria-label="`Schritt ${index + 1}: ${item.title}`">{{ index + 1 }}</RouterLink></nav>
    <figure v-if="step === 1" class="reference-image"><div class="pdf-reference"><FigmaPdfVorschau src="/medientechnik/figma/uebung-category/Category.pdf" /></div><figcaption>Vorlage: Kategorieseite der Einkaufs-App · <a href="/medientechnik/figma/uebung-category/Category.pdf" target="_blank" rel="noopener noreferrer">PDF in neuem Tab öffnen ↗</a></figcaption></figure>
    <section class="practice"><h2>{{ step }}. {{ current.title }}</h2><p>{{ current.intro }}</p><ol><li v-for="instruction in current.instructions" :key="instruction">{{ instruction }}</li></ol></section>
    <div class="reference"><a href="/medientechnik/figma/uebung-category/Category.pdf" target="_blank" rel="noopener noreferrer">Vorlage Category.pdf öffnen ↗</a><br /><a href="/medientechnik/figma/uebung-home/Assets.zip" download="Assets.zip">Assets aus Tutorial 3 herunterladen ↓</a><p>Nutze die Vorlage zum Vergleichen und die bekannten Assets für deine Gestaltung.</p></div>
    <section class="check"><h2>Prüfe dein Ergebnis</h2><p>{{ current.check }}</p></section>
    <nav class="pager" aria-label="Tutorialnavigation"><RouterLink v-if="step > 1" :to="link(step - 1)">← Zurück</RouterLink><RouterLink v-else to="/medientechnik/figma">← Zur Übersicht</RouterLink><span>{{ step }} / {{ steps.length }}</span><RouterLink v-if="step < steps.length" :to="link(step + 1)">Weiter →</RouterLink><RouterLink v-else to="/medientechnik/figma">Zur Übersicht →</RouterLink></nav>
  </div></main>
</template>

